# frozen_string_literal: true

require_relative 'abi_model'

module Erx
  module ABI
    # C declarations and fixed-prefix decoders are separate from whole-file
    # validation. Decoding a prefix never certifies its references or policy.
    module CEmitter
      NOTICE = <<~TEXT.freeze
        /*
         * Copyright (c) 2026, Stanislav Sedov <stas@deglitch.com>
         * SPDX-License-Identifier: BSD-2-Clause
         * Generated by tools/gen_abi.rb from abi/erx_abi.txt and its inputs.
         * Do not edit this file.
         */
      TEXT
      module_function

      def name(value)
        Names.c(value)
      end

      def constant(value)
        Names.macro(value)
      end

      def c_type(type)
        if type.is_a?(IntegerType)
          "#{type.signed ? 'int' : 'uint'}#{type.bits}_t"
        else
          "#{name(type.name)}_t"
        end
      end

      def literal(value, type)
        base = type.respond_to?(:integer) ? type.integer : type
        width = base.bits
        if value.negative?
          return "(-INT#{width}_C(#{base.maximum}) - INT#{width}_C(1))" if value == base.minimum
          "(-INT#{width}_C(#{-value}))"
        else
          "#{base.signed ? 'INT' : 'UINT'}#{width}_C(#{value})"
        end
      end

      def header(schema)
        out = [NOTICE, '#ifndef ERX_ABI_H', '#define ERX_ABI_H', '',
               '#include <stdbool.h>', '#include <stddef.h>',
               '#include <stdint.h>', '#include <stdatomic.h>', '',
               'typedef int32_t erx_status_t;',
               'typedef struct erx_rights erx_rights_t;',
               'struct erx_rights {', "\tuint32_t\tbits;", '};',
               '/* Only rights constructors publish values of this type. */', '']
        schema.constants.each_value do |item|
          out << "#define #{constant(item.name)} #{literal(item.value, item.type)}"
        end
        out << ''
        schema.type_order.each do |type_name|
          type = schema.types.fetch(type_name)
          out.concat(type_declaration(type))
          out << ''
        end
        out.concat(note_declaration(schema))
        schema.type_order.each do |type_name|
          type = schema.types.fetch(type_name)
          out.concat(layout_operations(type, schema)) if type.is_a?(Layout) && !type.private?
        end
        out.concat(status_table(schema))
        out.concat(signal_tables(schema))
        out.concat(event_tables(schema))
        out.concat(rights_tables(schema)) if schema.objects.any?
        out.concat(['#endif /* ERX_ABI_H */', ''])
        out.join("\n")
      end

      # Each private layout's header: its offsets, its definition and its
      # operations, after include/erx/abi.h, which declares only its tag,
      # size and alignment. The chokepoint rule generated for the layout
      # (tools/lib/erx/chokepoint_rules.rb) lets only its owner and the
      # owner's host tests include it.
      def private_headers(schema)
        layouts = schema.type_order.map { |type_name| schema.types.fetch(type_name) }
                        .select { |type| type.is_a?(Layout) && type.private? }
        layouts.to_h do |layout|
          guard = "ERX_#{File.basename(layout.private_header, '.h').upcase}_H"
          text = [NOTICE, "#ifndef #{guard}", "#define #{guard}", '',
                  '#include "erx/abi.h"', '',
                  "/* The definition of #{c_type(layout)}, private to #{layout.private_owner}. */",
                  *layout_offsets(layout), *layout_definition(layout), '',
                  *layout_operations(layout, schema), "#endif /* #{guard} */", '']
          [layout.private_header, text.join("\n")]
        end
      end

      # A layout's field, atomic and sequence operations.
      def layout_operations(layout, schema)
        out = layout.fields.flat_map do |field|
          bit_accessors(layout, field) + (field.atomic ? atomic_accessors(layout, field) : [])
        end
        layout.sequence ? out + sequence_accessors(layout, schema) : out
      end

      # For each enum with args lines, erx_<enum>_describe(value): the
      # member's name and typed arguments, or NULL for a value the enum
      # does not hold. A member without an args line has no arguments.
      # Like the rights lookups below, it indexes a constant table, and
      # its bound check comes before the index.
      def event_tables(schema)
        enums = schema.event_enums
        return [] if enums.empty?

        ['/* An event argument: an arg word read as a u64, an i64 or an erx_status_t; 0 marks an unused slot. */',
         'typedef enum erx_abi_arg_type {',
         *Model::EVENT_ARGUMENT_TYPES.each_with_index.map { |type, index| "\t#{event_type_tag(type)} = #{index + 1}," },
         '} erx_abi_arg_type_t;', '',
         'typedef struct erx_abi_event_arg {', "\tconst char\t\t*name;", "\terx_abi_arg_type_t\ttype;",
         '} erx_abi_event_arg_t;', '',
         '/* An event: its name and its first nargs arguments, in arg word order. */',
         'typedef struct erx_abi_event {', "\tconst char\t\t*name;", "\tuint32_t\t\tnargs;",
         "\terx_abi_event_arg_t\targs[#{Model::MAX_EVENT_ARGUMENTS}];",
         '} erx_abi_event_t;', '',
         *enums.flat_map { |type| event_lookup(type) }]
      end

      # erx_status_name(status): the ABI file's name of a status, or NULL
      # for a value no status holds. Statuses are 0 and negative, so the
      # table is indexed by the negated value, after its bound check.
      def status_table(schema)
        return [] if schema.statuses.nil? || schema.statuses.empty?

        entries = schema.statuses.sort_by { |_name, value| -value }.map do |name, value|
          "\t\t[#{-value}] = #{c_string(name)},"
        end
        ['/* The name of a status, as the ABI file spells it, or NULL. */',
         'static inline const char *', 'erx_status_name(erx_status_t status)', '{',
         "\tstatic const char *const table[] = {", *entries, "\t};", '',
         "\tif (status > 0 || (uint64_t)-(int64_t)status >= sizeof(table) / sizeof(table[0]))",
         "\t\treturn (NULL);", "\treturn (table[-(int64_t)status]);", '}', '']
      end

      # The signal table's lookups by number. Each table is indexed by
      # the number after its bound check, and an unlisted entry reads as
      # NULL or ERX_SIG_ACTION_NONE, which is 0.
      def signal_tables(schema)
        signals = schema.signals.signals
        return [] if signals.empty?

        names = signals.map { |signal| "\t\t[#{signal.number}] = #{signal_string(signal.name)}," }
        actions = signals.map { |signal| "\t\t[#{signal.number}] = #{constant("sig_action_#{signal.action}")}," }
        bound = "\tif (signo < 0 || (size_t)signo >= sizeof(table) / sizeof(table[0]))"
        ['/*', ' * The signal table\'s name of a number without SIG, in upper case (HUP,',
         ' * RTMIN+1, and THR for a reserved number), or NULL for an unlisted number.', ' */',
         'static inline const char *', 'erx_sig_name(int signo)', '{',
         "\tstatic const char *const table[] = {", *names, "\t};", '', bound,
         "\t\treturn (NULL);", "\treturn (table[signo]);", '}', '',
         '/* A signal\'s default action, an ERX_SIG_ACTION_ value: NONE for no signal. */',
         'static inline int', 'erx_sig_action(int signo)', '{',
         "\tstatic const uint8_t table[] = {", *actions, "\t};", '', bound,
         "\t\treturn (#{constant('sig_action_none')});", "\treturn (table[signo]);", '}', '',
         '/* Whether a number is a signal a program may name: listed and not reserved. */',
         'static inline bool', 'erx_sig_valid(int signo)', '{',
         "\tint action = erx_sig_action(signo);", '',
         "\treturn (action != #{constant('sig_action_none')} && action != #{constant('sig_action_reserved')});",
         '}', ''] + fault_table(schema)
      end

      # The fault table's lookup by fault kind (docs/design-programs.md, "A
      # program's end"), a switch over the kinds it lists.
      def fault_table(schema)
        return [] if schema.faults.empty?

        cases = schema.faults.flat_map do |row|
          ["\tcase #{constant("fault_#{row.kind}")}:", "\t\treturn (#{constant("sig#{row.signal.name}")});"]
        end
        ['/*', ' * The fault table\'s signal for a fault kind: a program whose thread faults',
         ' * with that kind ends as if by that signal, its space stopped with',
         " * #{constant('exit_signal')} plus the signal's number. 0 for #{constant('fault_exit')}, which",
         ' * marks an exit record, and for a number no fault kind holds.', ' */',
         'static inline int', 'erx_fault_signal(uint32_t kind)', '{', "\tswitch (kind) {", *cases,
         "\tdefault:", "\t\treturn (0);", "\t}", '}', '']
      end

      # A signal name in upper case as a C string literal: the table holds
      # only [a-z0-9+-], so it needs no escaping.
      def signal_string(name)
        raise SchemaError, "cannot quote signal #{name.inspect}" unless name.match?(/\A[a-z][a-z0-9+-]*\z/)
        "\"#{name.upcase}\""
      end

      def event_type_tag(type) = constant("abi_arg_#{type}")

      def event_lookup(type)
        entries = type.members.sort_by { |_member, value| value }.map do |member, _value|
          arguments = type.args.fetch(member, []).map do |argument|
            "{ #{c_string(argument.name)}, #{event_type_tag(argument.type)} }"
          end
          # C17 has no empty initializer; a static table zero-fills args.
          slots = arguments.empty? ? '' : ", .args = { #{arguments.join(', ')} }"
          label = constant("#{Model.constant_prefix(type.name)}_#{member}")
          "\t\t[#{label}] = { .name = #{c_string(member)}, .nargs = #{arguments.size}#{slots} },"
        end
        ["/* #{type.name}'s member numbered value, or NULL. */",
         'static inline const erx_abi_event_t *',
         "#{name(type.name)}_describe(#{c_type(type.base)} value)", '{',
         "\tstatic const erx_abi_event_t table[] = {", *entries, "\t};", '',
         "\tif (value >= sizeof(table) / sizeof(table[0]) || table[value].name == NULL)",
         "\t\treturn (NULL);", "\treturn (&table[value]);", '}', '']
      end

      # A validated identifier as a C string literal: it holds only
      # [a-z0-9_], so it needs no escaping.
      def c_string(identifier)
        raise SchemaError, "cannot quote #{identifier.inspect}" unless identifier.match?(/\A[a-z][a-z0-9_]*\z/)
        "\"#{identifier}\""
      end

      # The object types' carryable and pass sets and the creation kinds'
      # types and default sets, as lookups over the ABI file's declarations.
      # They return plain masks: only kernel/core/cap.c turns one into an
      # erx_rights_t (erx_rights_create), so these grant nothing by
      # themselves. A number that names no type or kind yields 0. Each
      # lookup indexes a constant table rather than switching, so no
      # optimisation level compiles it to an indirect branch, which the
      # kernel's stack proof refuses. An ABI file that declares no kinds
      # gets kind lookups that name nothing, since C17 has no empty array.
      def rights_tables(schema)
        mask = lambda do |names|
          names.empty? ? "UINT32_C(0)" : names.sort.map { |right| constant("hr_#{right}") }.join(" |\n\t\t    ")
        end
        lookup = lambda do |result, function, argument, cases|
          number = argument.split.last
          if cases.empty?
            next ['static inline uint32_t', "#{function}(#{argument})", '{', "\t(void)#{number};",
                  "\treturn (#{result});", '}', '']
          end

          ['static inline uint32_t', "#{function}(#{argument})", '{', "\tstatic const uint32_t table[] = {",
           *cases.map { |label, value| "\t\t[#{label}] = #{value}," }, "\t};", '',
           "\tif (#{number} >= sizeof(table) / sizeof(table[0]))", "\t\treturn (#{result});",
           "\treturn (table[#{number}]);", '}', '']
        end
        types = schema.objects.map { |name, object| [constant("k_#{name}"), object.fetch(:sets)] }
        kinds = schema.kinds.map { |name, kind| [constant("kind_#{name}"), kind] }
        ['/* An object type and a creation kind, numbered by the ABI file. */',
         'typedef uint32_t erx_ktype_t;', 'typedef uint32_t erx_create_kind_t;', '',
         '/* The rights a capability of the type can carry. */',
         *lookup.call('UINT32_C(0)', 'erx_ktype_rights_mask', 'erx_ktype_t type',
                      types.map { |label, sets| [label, mask.call(sets.fetch('rights'))] }),
         '/* The rights it keeps when it passes to a peer; 0: it never passes. */',
         *lookup.call('UINT32_C(0)', 'erx_ktype_pass_mask', 'erx_ktype_t type',
                      types.map { |label, sets| [label, mask.call(sets.fetch('pass'))] }),
         '/* The type of object a creation kind makes. */',
         *lookup.call('UINT32_C(0)', 'erx_kind_ktype', 'erx_create_kind_t kind',
                      kinds.map { |label, kind| [label, constant("k_#{kind.fetch(:type)}")] }),
         '/* The rights a creation of the kind returns. */',
         *lookup.call('UINT32_C(0)', 'erx_kind_default_mask', 'erx_create_kind_t kind',
                      kinds.map { |label, kind| [label, mask.call(kind.fetch(:default))] }),
         *root_slot_tables(schema, lookup)]
      end

      # The root task's well-known slots: the kind each is installed as,
      # 0 for a slot the ABI file does not name, and whether the boot may
      # leave it null.
      def root_slot_tables(schema, lookup)
        return [] if schema.caps.empty?

        slots = schema.caps.map { |name, cap| [constant("root_slot_#{name}"), cap] }
        ['/* The creation kind a root slot holds; 0: no root capability. */',
         *lookup.call('UINT32_C(0)', 'erx_root_slot_kind', 'uint32_t slot',
                      slots.map { |label, cap| [label, constant("kind_#{cap.fetch(:kind)}")] }),
         '/* 1 when the boot may leave the root slot ERX_CAP_NULL, else 0. */',
         *lookup.call('UINT32_C(0)', 'erx_root_slot_optional', 'uint32_t slot',
                      slots.map { |label, cap| [label, cap.fetch(:optional) ? 'UINT32_C(1)' : 'UINT32_C(0)'] })]
      end

      def sequence_accessors(layout, schema)
        sequence = layout.sequence
        field = layout.fetch_field(sequence.fetch(:field))
        status_name = "e#{sequence.fetch(:exhaustion).delete_prefix('@')}"
        status = schema.constants.fetch(status_name)
        prefix = "#{constant(layout.name)}_#{field.name.upcase}"
        ["#define #{prefix}_TERMINAL #{literal(sequence.fetch(:terminal), field.type)}",
         "#define #{prefix}_EXHAUSTION #{constant(status.name)}", '',
         '/* Tests a captured sequence value; it does not validate a snapshot. */',
         'static inline erx_status_t',
         "#{name(layout.name)}_#{field.name}_status(#{c_type(field.type)} captured)", '{',
         "\treturn (captured == #{prefix}_TERMINAL ? #{prefix}_EXHAUSTION : ERX_OK);", '}', '']
      end

      def type_declaration(type)
        case type
        when ScalarType
          tag = name(type.name)
          ["typedef struct #{tag} #{tag}_t;", "struct #{tag} {",
           "\t#{c_type(type.base)}\traw;", '};',
           "_Static_assert(sizeof(#{tag}_t) == #{type.size}, \"#{tag} size\");"]
        when EnumType
          ["typedef #{c_type(type.base)} #{c_type(type)};"]
        when BytesType
          result = ["typedef uint8_t #{c_type(type)}[#{type.size}];"]
          if type.fixed
            bytes = type.fixed.bytes.map { |byte| format('0x%02x', byte) }.join(', ')
            result << "#define #{constant(type.name)}_SIZE #{type.size}"
            result << "#define #{constant(type.name)}_BYTES { #{bytes} }"
            escaped = c_string_content(type.fixed)
            result << "#define #{constant(type.name)}_STRING \"#{escaped}\""
          end
          result
        when Layout
          layout_declaration(type)
        else
          raise SchemaError, "cannot emit C type #{type.name}"
        end
      end

      # A private layout leaves include/erx/abi.h with an incomplete type:
      # its tag, and the size and alignment a caller needs to allocate one;
      # private_headers emits the rest.
      def layout_declaration(layout)
        tag = name(layout.name)
        prefix = constant(layout.name)
        extent = ["#define #{prefix}_SIZE #{layout.size}",
                  "#define #{prefix}_ALIGN #{layout.alignment}"]
        typedef = "typedef struct #{tag} #{tag}_t;"
        return [*extent, typedef] if layout.private?

        [*extent, *layout_offsets(layout), typedef, *layout_definition(layout)]
      end

      def layout_offsets(layout)
        prefix = constant(layout.name)
        layout.fields.map { |field| "#define #{prefix}_OFF_#{field.name.upcase} #{field.offset}" }
      end

      # The record and the assertions that pin its size, alignment and
      # offsets to the ABI file's.
      def layout_definition(layout)
        tag = name(layout.name)
        prefix = constant(layout.name)
        out = ["struct #{tag} {"]
        members = layout.fields.map { |field| [field.offset, :field, field] }
        layout.padding.each_with_index { |range, index| members << [range[0], :padding, [index, range[1]]] }
        members.sort_by(&:first).each_with_index do |(_offset, kind, member), index|
          align = index.zero? ? "_Alignas(#{layout.alignment}) " : ''
          if kind == :padding
            out << "\t#{align}uint8_t\tpadding_#{member[0]}[#{member[1]}];"
          else
            atomic = member.atomic ? '_Atomic ' : ''
            count = member.array? ? "[#{member.count}]" : ''
            out << "\t#{align}#{atomic}#{c_type(member.type)}\t#{member.name}#{count};"
          end
        end
        if layout.tail
          out << "\t#{c_type(layout.tail.type)}\t#{layout.tail.name}[];"
        end
        out << '};'
        out << "_Static_assert(sizeof(#{tag}_t) == #{prefix}_SIZE, \"#{tag} size\");"
        out << "_Static_assert(_Alignof(#{tag}_t) == #{prefix}_ALIGN, \"#{tag} alignment\");"
        layout.fields.each do |field|
          out << "_Static_assert(offsetof(#{tag}_t, #{field.name}) =="
          out << "    #{prefix}_OFF_#{field.name.upcase}, \"#{tag}.#{field.name} offset\");"
        end
        if layout.tail
          out << "_Static_assert(offsetof(#{tag}_t, #{layout.tail.name}) == #{prefix}_SIZE,"
          out << "    \"#{tag}.#{layout.tail.name} offset\");"
        end
        out
      end

      def note_declaration(schema)
        layout = schema.types['erx_abi_note']
        return [] unless layout
        fields = layout.fields.to_h { |field| [field.name, field] }
        unless fields.keys == %w[header owner abi_version] &&
               fields.fetch('header').type.name == 'erx_elf64_nhdr' &&
               fields.fetch('owner').type.name == 'abi_note_owner' &&
               fields.fetch('abi_version').type.name == 'u32'
          raise SchemaError, 'ABI note declaration does not match the startup interface'
        end
        section = schema.types.fetch('abi_note_section')
        unless section.is_a?(BytesType) && section.fixed && section.fixed.bytes.all? { |byte| byte.between?(33, 126) }
          raise SchemaError, 'ABI note section must be a printable ASCII name'
        end
        [
          '/* Emit once from target startup; the linker keeps this note section. */',
          '#define ERX_DECLARE_ABI_NOTE(symbol) \\',
          '\tstatic const erx_abi_note_t symbol \\',
          '\t    __attribute__((__used__, __section__(ERX_ABI_NOTE_SECTION_STRING), \\',
          '\t    __aligned__(ERX_ABI_NOTE_ALIGN))) = { \\',
          '\t\t.header = { .n_namesz = ERX_ABI_NOTE_OWNER_SIZE, \\',
          "\t\t    .n_descsz = #{fields.fetch('abi_version').type.size}, .n_type = ERX_ABI_NOTE_TYPE }, \\",
          '\t\t.owner = ERX_ABI_NOTE_OWNER_BYTES, \\',
          '\t\t.abi_version = ERX_ABI_VERSION \\',
          '\t}', ''
        ].map { |line| line.gsub('\\t', "\t") }
      end

      def c_string_content(bytes)
        bytes.bytes.map do |byte|
          case byte
          when 34 then '\\"'
          when 63 then '\\?'
          when 92 then '\\\\'
          when 32..126 then byte.chr
          else format('\\%03o', byte)
          end
        end.join
      end

      def bit_accessors(layout, field)
        base = field.type.respond_to?(:integer) ? field.type.integer : nil
        field.bits.flat_map do |bits|
          width = bits.fetch(:high) - bits.fetch(:low) + 1
          mask = (1 << width) - 1
          semantic_max = mask << bits.fetch(:shift)
          unsigned = "uint#{base.bits}_t"
          prefix = "#{name(layout.name)}_#{field.name}_#{bits.fetch(:name)}"
          raw = field.type.strong? ? 'value.raw' : 'value'
          result = ["static inline #{unsigned}",
                    "#{prefix}_get(#{c_type(field.type)} value)", '{',
                    "\treturn (((#{unsigned})#{raw} >> #{bits.fetch(:low)} & #{unsigned_literal(mask, base.bits)}) << #{bits.fetch(:shift)});",
                    '}', '', 'static inline bool',
                    "#{prefix}_set(#{c_type(field.type)} *value, #{unsigned} bits)", '{',
                    "\t#{unsigned} raw;", '']
          result << "\tif (value == NULL || bits > #{unsigned_literal(semantic_max, base.bits)})"
          result << "\t\treturn (false);"
          if bits.fetch(:shift).positive?
            result << "\tif ((bits & #{unsigned_literal((1 << bits.fetch(:shift)) - 1, base.bits)}) != 0)"
            result << "\t\treturn (false);"
          end
          dereference = field.type.strong? ? 'value->raw' : '*value'
          result << "\traw = (#{unsigned})#{dereference};"
          result << "\traw = (raw & ~#{unsigned_literal(mask << bits.fetch(:low), base.bits)}) |"
          result << "\t    ((bits >> #{bits.fetch(:shift)}) << #{bits.fetch(:low)});"
          assignment = base.signed ? signed_expression('raw', base) : 'raw'
          result << "\t#{dereference} = #{assignment};"
          result.concat(["\treturn (true);", '}', ''])
          result
        end
      end

      def atomic_accessors(layout, field)
        prefix = "#{name(layout.name)}_#{field.name}"
        layout_type = c_type(layout)
        field_type = c_type(field.type)
        index_arg = field.array? ? ', size_t index' : ''
        selected = field.array? ? "#{field.name}[index]" : field.name
        condition = field.array? ? "record == NULL || value == NULL || index >= #{field.count}" : 'record == NULL || value == NULL'
        out = ['/* Each successful accessor performs one atomic element access. */',
               'static inline bool',
               "#{prefix}_load(const #{layout_type} *record#{index_arg}, #{field_type} *value)", '{',
               "\tif (#{condition})", "\t\treturn (false);",
               "\t*value = atomic_load_explicit(&record->#{selected},",
               "\t    memory_order_#{field.atomic.fetch(:load)});", "\treturn (true);", '}', '']
        unless field.atomic.fetch(:store) == 'none'
          condition = field.array? ? "record == NULL || index >= #{field.count}" : 'record == NULL'
          out.concat(['static inline bool',
                      "#{prefix}_store(#{layout_type} *record#{index_arg}, #{field_type} value)", '{',
                      "\tif (#{condition})", "\t\treturn (false);",
                      "\tatomic_store_explicit(&record->#{selected}, value,",
                      "\t    memory_order_#{field.atomic.fetch(:store)});", "\treturn (true);", '}', ''])
        end
        out
      end

      def unsigned_literal(value, width)
        "UINT#{width}_C(#{value})"
      end

      def signed_expression(raw, base)
        unsigned = "uint#{base.bits}_t"
        "(#{raw} <= #{unsigned_literal(base.maximum, base.bits)} ? " \
          "(#{c_type(base)})#{raw} : -INT#{base.bits}_C(1) - " \
          "(#{c_type(base)})(#{unsigned_literal((1 << base.bits) - 1, base.bits)} - (#{unsigned})#{raw}))"
      end

      def reader_header(schema)
        layouts = schema.type_order.map { |key| schema.types.fetch(key) }
                        .select { |type| type.is_a?(Layout) && type.storage == 'wire_le' }
        out = [NOTICE, '#ifndef ERX_ABI_READER_H', '#define ERX_ABI_READER_H', '',
               '#include "erx/abi.h"', '',
               '/* Prefix decoders borrow immutable bytes; references remain untrusted. */']
        layouts.each do |layout|
          out << "bool #{name(layout.name)}_decode(const uint8_t *bytes, size_t length,"
          out << "    #{c_type(layout)} *result);"
        end
        out.concat(['', 'typedef struct erx_abi_error erx_abi_error_t;',
                    'struct erx_abi_error {', "\tconst char\t*reason;",
                    "\tconst char\t*field;", "\tsize_t\t\t offset;", '};', ''])
        schema.readers.each do |reader|
          prefix = Names.c(reader.name)
          out.concat(["typedef struct #{prefix}_view #{prefix}_view_t;",
                      "struct #{prefix}_view {", "\tconst uint8_t\t*bytes;",
                      "\tsize_t\t\t length;", "\t#{c_type(reader.root)}\theader;", '};',
                      "bool #{prefix}_open(const uint8_t *bytes, size_t length,",
                      "    #{prefix}_view_t *result, erx_abi_error_t *error);", ''])
          reader.tables.each_value do |table|
            out << "bool #{prefix}_#{table.fetch(:name)}_at(const #{prefix}_view_t *view,"
            out << "    size_t index, #{c_type(table.fetch(:type))} *result);"
          end
          out << ''
        end
        out.concat(['#endif /* ERX_ABI_READER_H */', ''])
        out.join("\n")
      end

      def prefix_source(schema)
        out = [NOTICE, '#include "erx/abi_reader.h"', '#include "erx/cdefs.h"', '']
        [16, 32, 64].each do |width|
          out << "static uint#{width}_t erx_abi_load_u#{width}(const uint8_t *) ERX_UNUSED;"
        end
        out << ''
        [16, 32, 64].each do |width|
          out.concat(["static uint#{width}_t", "erx_abi_load_u#{width}(const uint8_t *bytes)", '{',
                      "\tuint#{width}_t value;", '', "\tvalue = 0;",
                      "\tfor (size_t index = 0; index < #{width / 8}; index++)",
                      "\t\tvalue |= (uint#{width}_t)bytes[index] << (index * 8);",
                      "\treturn (value);", '}', ''])
        end
        schema.type_order.each do |type_name|
          layout = schema.types.fetch(type_name)
          next unless layout.is_a?(Layout) && layout.storage == 'wire_le'
          out.concat(prefix_decoder(layout))
        end
        out.join("\n")
      end

      def prefix_decoder(layout)
        out = ['bool', "#{name(layout.name)}_decode(const uint8_t *bytes, size_t length,",
               "    #{c_type(layout)} *result)", '{', "\t#{c_type(layout)} value = {0};", '',
               "\tif (bytes == NULL || result == NULL || length < #{constant(layout.name)}_SIZE)",
               "\t\treturn (false);", '']
        layout.fields.each do |field|
          if field.array?
            out << "\tfor (size_t index = 0; index < #{field.count}; index++) {"
            out.concat(decode_field(field.type, "value.#{field.name}[index]",
                                    "#{field.offset} + index * #{field.type.size}", indent: "\t\t"))
            out << "\t}"
          else
            out.concat(decode_field(field.type, "value.#{field.name}", field.offset.to_s, indent: "\t"))
          end
        end
        out.concat(['', "\t*result = value;", "\treturn (true);", '}', ''])
        out
      end

      def decode_field(type, destination, offset, indent:)
        if type.is_a?(Layout)
          ["#{indent}if (!#{name(type.name)}_decode(bytes + #{offset},",
           "#{indent}    #{constant(type.name)}_SIZE, &#{destination}))",
           "#{indent}\treturn (false);"]
        elsif type.is_a?(BytesType)
          ["#{indent}for (size_t byte = 0; byte < #{type.size}; byte++)",
           "#{indent}\t#{destination}[byte] = bytes[#{offset} + byte];"]
        else
          base = type.integer
          load = base.bits == 8 ? "bytes[#{offset}]" : "erx_abi_load_u#{base.bits}(bytes + #{offset})"
          target = type.strong? ? "#{destination}.raw" : destination
          if base.signed
            ["#{indent}{", "#{indent}\tuint#{base.bits}_t raw;", '',
             "#{indent}\traw = #{load};", "#{indent}\t#{target} = #{signed_expression('raw', base)};",
             "#{indent}}"]
          else
            ["#{indent}#{target} = #{load};"]
          end
        end
      end

      # The typed parameters every backend's wrapper of a call shares: an
      # integer argument by value, an aggregate by pointer, each result
      # through an out pointer.
      def call_parameters(call)
        arguments = call.fetch(:arguments).map do |argument|
          type = argument.fetch(:type)
          type.respond_to?(:integer) ? "#{c_type(type)} #{argument.fetch(:name)}" : "const #{c_type(type)} *#{argument.fetch(:name)}"
        end
        arguments + call.fetch(:results).map { |result| "#{c_type(result.fetch(:type))} *out_#{result.fetch(:name)}" }
      end

      def call_header(schema)
        out = [NOTICE, '#ifndef ERX_GENERATED_CALLS_H', '#define ERX_GENERATED_CALLS_H', '',
               '#include "erx/abi.h"', '']
        schema.calls.each do |name, call|
          arguments = call_parameters(call)
          out << "erx_status_t erx_#{name}(#{arguments.empty? ? 'void' : arguments.join(', ')});"
        end
        out.concat(['', '#endif /* ERX_GENERATED_CALLS_H */', ''])
        out.join("\n")
      end
    end
  end
end
